messages.content:
module fluorescence

manifest sample
manifest capture_antibody_beads
manifest reporter_antibody_hrp
manifest wash_buffer
manifest chemiluminescent_substrate

instructions:

// Step 1: dispense sample, capture-antibody magnetic beads, and HRP-labeled
// reporter antibody, then merge them at the reaction site
assay_sample = dispense 10 units of sample
beads = dispense 10 units of capture_antibody_beads
reporter = dispense 10 units of reporter_antibody_hrp

mix1 = mix assay_sample with beads
reaction_mix = mix mix1 with reporter

// Step 2: incubate (shuttle/resuspend) to form the sandwich complex
heat reaction_mix at 25c for 180s

// Steps 3-5: magnetically immobilize the beads and perform 5 cycles of
// dilution-based washing (~1:6 dilution per cycle, ~7776-fold cumulative)
repeat 5 times {
    wash = dispense 10 units of wash_buffer
    washed = mix reaction_mix with wash
    dispose washed
}

// Step 6: release from the magnet and resuspend the washed beads
heat reaction_mix at 25c for 10s

// Step 7: merge with chemiluminescent (HRP) substrate to initiate the reaction
substrate = dispense 10 units of chemiluminescent_substrate
detection_mix = mix reaction_mix with substrate
heat detection_mix at 25c for 60s

// Step 8: transport to the detection site and read the endpoint
// chemiluminescent signal (photon-counting detector)
assay_signal = detect fluorescence on detection_mix for 30s

dispose detection_mix
